head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.vID;
scwin.fr_queryId; // 종목 query id
scwin.vBzProcsNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vID = parentWin.clickID;
        const pGubun = parentWin.fn_pGubun;
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        const vIsuCd = parentWin.clickIsuCd;
        const vIsuNm = parentWin.clickIsuNm;
        const vUsrId = parentWin.clickIntegUsrId;
        const vIUsrNm = parentWin.clickIntegUsrNm;
        txb_ISU_CD.setValue(vIsuCd);
        txb_ISU_NM.setValue(vIsuNm);
        txb_INTEG_USR_ID.setValue(vUsrId);
        txb_EMP_NM.setValue(vIUsrNm);

        // 신규 팝업창으로 open 됐을 경우,
        if (pGubun === "I") {
            btn_delete.setDisabled(true);
            btn_delete.setBackgroundImage("../img/btn_delete_d.gif");
        } else if (pGubun === "D") {
            btn_insert.setDisabled(true);
            // btn_insert.src = "../img/btn_reg_d.gif"; // reg_d.gif 파일이 존재하지 않으므로 다른 이미지 파일로 대체
            btn_insert.setBackgroundImage("../img/btn_save_d.gif");

            // 종목,상장신청인 search disable 처리
            img_SearchIsu.setDisabled(true);
            img_SearchUrs.setDisabled(true);
            img_SearchIsu.setBackgroundImage("../img/btn_search_d.gif");
            img_SearchUrs.setBackgroundImage("../img/btn_search_d.gif");
        } else {
            // just view screen. (not delete, not insert)

            btn_delete.setDisabled(true);
            btn_delete.setBackgroundImage("../img/btn_delete_d.gif");
            btn_insert.setDisabled(true);
            // btn_insert.src = "../img/btn_reg_d.gif";  // reg_d.gif 파일이 존재하지 않으므로 다른 이미지 파일로 대체
            btn_insert.setBackgroundImage("../img/btn_save_d.gif");

            // 종목,상장신청인 search disable 처리
            img_SearchIsu.setDisabled(true);
            img_SearchUrs.setDisabled(true);
            img_SearchIsu.setBackgroundImage("../img/btn_search_d.gif");
            img_SearchUrs.setBackgroundImage("../img/btn_search_d.gif");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70071.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_SearchIsu_onclick
 * @description img_SearchIsu 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_SearchIsu_onclick = async function() {
    try {
        // 기존값 초기화
        if (txb_ISU_CD.getValue() !== "") {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: setObjectValue(txb_ISU_CD) = "";*/
            X = ""; /*ORG SRC: setObjectValue(txb_ISU_NM) = "";*/ X = "";
        }

        // (종목명변경)종목코드 조회
        fn_GetPar = scwin.getParIsuCd;
        fn_SetPar = scwin.setParIsuCd;
        scwin.fr_queryId = "lds.stf.digital.select.secuisuall_p2.condition";
        const options = {
            id: "ULDSTF70017_3",
            title: "종목 선택",
            type: "browserPopup",
            width: "430px",
            height: 550 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../digital/ULDSTF70017_3.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.img_SearchIsu_onclick" });
    }
};

/**
 * @method
 * @name img_SearchUrs_onclick
 * @description img_SearchUrs 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_SearchUrs_onclick = async function() {
    try {
        // 기존값 초기화
        if (txb_INTEG_USR_ID.getValue() !== "") {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: setObjectValue(txb_INTEG_USR_ID) = "";*/
            X = ""; /*ORG SRC: setObjectValue(txb_EMP_NM) = "";*/ X = "";
        }
        // 상장신청인명 조회
        fn_GetParIsur = scwin.getParUsrId;
        fn_SetParIsur = scwin.setParUsrId;
        const options = {
            id: "ULDSTF70017_4",
            title: "상장신청인 선택",
            type: "browserPopup",
            width: "430px",
            height: 550 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../digital/ULDSTF70017_4.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.img_SearchUrs_onclick" });
    }
};

/**
 * @method
 * @name btn_insert_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_insert_onclick = async function() {
    try {
        // 등록 버튼
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("종목을 입력해주세요.");
            return;
        }
        if (txb_INTEG_USR_ID.getValue() === "") {
            await $c.win.alert("상장신청인을 입력해주세요.");
            return;
        }
        if (window.confirm("[등록]하시겠습니까?")) {
            //    dts_input.DataID =  "/digital/DigitalListinvstg.do?method=listDigitalAinvst&messageId=DIGITAL_AINVSTLIST_OUT";
            //    dts_input.reset();

            let isuCd = txb_ISU_CD.getValue(); // 종목cd
            const listTbClssCd = ""; // 상장유형분류코드
            let integUsrId = txb_INTEG_USR_ID.getValue(); // 상장신청인id
            const pubofrYn = ""; // 공모여부

            trs_Save.KeyName = "toinb_dataid4";
            // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     ISU_CD : isuCd,
            //     INTEG_USR_ID : integUsrId,
            //     REG_ID : js_emp_no
            // };
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/digital/DigitalListinvstg.do",
                ref : "dts_input",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.btn_insert_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lcd.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lcd.fn_alertMsg('S1');
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        // 삭제 버튼

        if (window.confirm("[삭제]하시겠습니까?")) {
            let isuCd = txb_ISU_CD.getValue(); // 종목cd
            let integUsrId = txb_INTEG_USR_ID.getValue(); // 상장신청인id

            trs_Save.KeyName = "toinb_dataid4";
            // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     BZ_PROCS_NO : scwin.vBzProcsNo,
            //     ISU_CD : isuCd,
            //     INTEG_USR_ID : integUsrId,
            //     ADJPRN_ID : js_emp_no
            // };
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/digital/DigitalListinvstg.do",
                ref : "dts_input",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70071.btn_delete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 종목
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};

/**
 * @method
 * @name getParUsrId
 * @description 상장신청인
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUsrId = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_INTEG_USR_ID.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_EMP_NM.getValue(); // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParUsrId
 * @description set Par Usr Id 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParUsrId = function(arrPar) {
    let dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_INTEG_USR_ID.setValue(arrPar[0].ISU_CD);
        txb_EMP_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
};
